549: // createHelpTemplate is the template for the create command help
550: func createHelpTemplate(cmd *cobra.Command) *template.Template {
551: 	body := cmd.Long + "\n\n" + cmd.UsageString()
552: 	t := template.New("help")
553: 	fm := template.FuncMap{
554: 		"indent": func(i int, c string, v string) string {
555: 			indentation := strings.Repeat(c, i)
556: 			return indentation + strings.Replace(v, "\n", "\n"+indentation, -1)
557: 		},
558: 	}
559: 	t.Funcs(fm)
560: 	return template.Must(t.Parse(body))
561: }
