563: // runtimeTemplateOptions is a human-friendly table of valid Language Runtime
564: // to Template combinations.
565: func runtimeTemplateOptions(client *fn.Client) (string, error) {
566: 	runtimes, err := client.Runtimes()
567: 	if err != nil {
568: 		return "", err
569: 	}
570: 	builder := strings.Builder{}
571: 	writer := tabwriter.NewWriter(&builder, 0, 0, 3, ' ', 0)
572: 
573: 	fmt.Fprint(writer, "Language\tTemplate\n")
574: 	fmt.Fprint(writer, "--------\t--------\n")
575: 	for _, r := range runtimes {
576: 		templates, err := client.Templates().List(r)
577: 		// Not all language packs will have templates for
578: 		// all available runtimes. Without this check
579: 		if err != nil && !errors.Is(err, fn.ErrTemplateNotFound) {
580: 			return "", err
581: 		}
582: 		for _, t := range templates {
583: 			fmt.Fprintf(writer, "%v\t%v\n", r, t) // write tabbed
584: 		}
585: 	}
586: 	writer.Flush()
587: 	return builder.String(), nil
588: }
